/* ═════════════════ NAV ═════════════════ */
function switchView(v){
  $$(".view").forEach(x=>x.classList.remove("active"));
  $$(".nav-btn").forEach(b=>b.classList.toggle("active",b.dataset.view===v));
  const el=$("#view-"+v); el.classList.add("active");
  window.scrollTo({top:0,behavior:"smooth"});
  el.querySelectorAll(".reveal").forEach((r,i)=>{r.classList.remove("in");setTimeout(()=>r.classList.add("in"),60+i*50)});
  // re-animar barras del view
  setTimeout(()=>{el.querySelectorAll(".bar-fill").forEach(b=>{b.style.width="0";requestAnimationFrame(()=>requestAnimationFrame(()=>b.style.width=b.dataset.w))});
    el.querySelectorAll(".stack span").forEach(s=>{if(s.dataset.w){s.style.width="0";requestAnimationFrame(()=>requestAnimationFrame(()=>s.style.width=s.dataset.w))}})},120);
  if(v==="dashboard") runCounts();
}
$$(".nav-btn").forEach(b=>b.addEventListener("click",()=>switchView(b.dataset.view)));
document.addEventListener("click",e=>{
  const j=e.target.closest("[data-view-jump]"); if(j) switchView(j.dataset.viewJump);
  const t=e.target.closest("[data-toast]"); if(t) toast(t.dataset.toast);
});

