/* ═════════════════ COUNTDOWN ═════════════════ */
const CD_TARGET=new Date("2026-09-10T23:59:00");
function tickCd(){const real=new Date();let diff=CD_TARGET-real;
  if(diff<0){const live=new Date(real.getTime()+ (1000*60*60*49.4)); diff=live-real;} // demo: siempre visible
  const d=Math.floor(diff/864e5),h=Math.floor(diff/36e5)%24,m=Math.floor(diff/6e4)%60,s=Math.floor(diff/1e3)%60;
  $("#cdD").textContent=d;$("#cdH").textContent=String(h).padStart(2,"0");$("#cdM").textContent=String(m).padStart(2,"0");$("#cdS").textContent=String(s).padStart(2,"0");}
setInterval(tickCd,1000); tickCd();

/* ═════════════════ CONTADORES ═════════════════ */
let counted=false;
function runCounts(){if(counted)return;counted=true;
  $$(".count").forEach(el=>{const target=parseFloat(el.dataset.v),dec=+el.dataset.d,t0=performance.now();
    const step=t=>{const p=Math.min((t-t0)/1400,1),e=1-Math.pow(1-p,3);el.textContent=(target*e).toFixed(dec);if(p<1)requestAnimationFrame(step)};
    requestAnimationFrame(step);});}

