function stackHTML(w){return `<div class="stack" title="Quizzes ${w[0]}% · Labs ${w[1]}% · Parcial ${w[2]}% · Final ${w[3]}%">
 <span class="wq" data-w="${w[0]}%"></span><span class="wl" data-w="${w[1]}%"></span><span class="wm" data-w="${w[2]}%"></span><span class="wf" data-w="${w[3]}%"></span></div>`}
function stChip(st,g){if(st==="done")return `<span class="st"><span class="gr" style="color:var(--green)">${g.toFixed(1)}</span><br><span style="color:var(--green);font-size:9.5px">SUPERADO ✓</span></span>`;
 if(st==="now")return `<span class="st"><span class="chip a" style="animation:pulse 2.2s infinite">● EN CURSO</span></span>`;
 return `<span class="st"><span class="chip">PLANIFICADO</span></span>`}
function modDetail(m){
  const topics=m.topics.map(t=>`<span class="chip">${t}</span>`).join("");
  if(m.st==="done")return `<div><h5>Syllabus clave</h5><div class="topics">${topics}</div></div>
   <div><h5>Acta cerrada</h5><div class="archived">Quizzes (4): media <b>${m.avgs.q.toFixed(1)}</b><br>Examen parcial: <b>${m.avgs.m.toFixed(1)}</b>${m.avgs.f?`<br>Examen final: <b>${m.avgs.f.toFixed(1)}</b>`:"<br>Final: evaluación por práctica integrada"}<br>Nota final del módulo: <b>${m.g.toFixed(1)} / 10</b></div></div>`;
  if(m.st==="now"){
   const qs=m.quizzes.map(q=>`<div class="ev-row"><span class="d ${q.s!==null?"past":""}">${fmtD(q.d)}</span><b>${q.n}</b><span class="pts ${q.s===null?"pend":q.s>=8?"ok":"md"}">${q.s===null?"PENDIENTE":q.s.toFixed(1)}</span></div>`).join("");
   const ex=m.exams.map(x=>`<div class="ev-row"><span class="d">${fmtD(x.d)}</span><b>${x.n}</b> · ${x.mode}<span class="pts pend">${x.dur} · ${x.p}%</span></div>`).join("");
   return `<div><h5>Syllabus clave · quizzes</h5><div class="topics" style="margin-bottom:12px">${topics}</div>${qs}</div><div><h5>Exámenes programados</h5>${ex}</div>`;}
  return `<div><h5>Syllabus previsto</h5><div class="topics">${topics}</div></div><div><h5>Estado</h5><div class="archived">${m.plan}<br>Distribución: Q${m.w[0]} · LAB${m.w[1]} · PARC${m.w[2]} · FIN${m.w[3]}</div></div>`;
}
function renderCurriculum(){
  let html="";
  PROGRAM.forEach(y=>{ y.sems.forEach(sem=>{
    const cr=sem.mods.reduce((a,m)=>a+m.cr,0);
    html+=`<div class="sem" data-year="${y.y}">
      <div class="sem-head"><h2>${sem.id} · ${y.title.split("·")[1].trim()}</h2><span class="term">${sem.term}</span><span class="meta">${sem.mods.length} módulos · ${cr} créditos</span></div>`;
    sem.mods.forEach(m=>{
      html+=`<details class="mod"><summary>
        <span class="code">${m.code}</span>
        <span class="nm"><b>${m.name}</b><span>${m.prof} · ${m.st==="now"?"4 quizzes activos ·":"histórico archivado ·"} ${m.w[0]}/${m.w[1]}/${m.w[2]}/${m.w[3]}</span></span>
        <span class="cr">${m.cr}<small>ECTS</small></span>
        ${stackHTML(m.w)}
        ${stChip(m.st,m.g||0)}
        <span class="chev">▾</span>
      </summary><div class="mod-body">${modDetail(m)}</div></details>`;
    });
    html+=`</div>`;
  });});
  $("#curriculumBody").innerHTML=html;
}
