function renderAssess(){
  const now=PROGRAM[2].sems[1]; // S6
  let pq=[];
  now.mods.forEach(m=>m.quizzes&&m.quizzes.forEach(q=>{if(q.s===null)pq.push({...q,code:m.code,mod:m.name})}));
  pq.sort((a,b)=>a.d.localeCompare(b.d));
  $("#quizCount").textContent=pq.length+" PENDIENTES";
  $("#pendingQuizzes").innerHTML=pq.map(q=>{
    const dl=daysLeft(q.d);
    const cls=dl<=2?"urgent":dl<=6?"soon":"later";
    const d=new Date(q.d+"T12:00:00");
    return `<div class="quiz-item">
      <div class="q-date"><b>${String(d.getDate()).padStart(2,"0")}</b><span>${d.toLocaleDateString("es-ES",{month:"short"}).toUpperCase().replace(".","")}</span></div>
      <div class="qi"><b>${q.mod} · ${q.n}</b><span>${q.code} · ventana única 60 min · Honor Code firmado</span></div>
      <span class="dleft ${cls}">${dl<=0?"HOY":dl+" días"}</span>
      <div class="w"><b>8%</b><span>del módulo</span></div>
    </div>`;}).join("");
  let ex=[]; now.mods.forEach(m=>m.exams&&m.exams.forEach(x=>ex.push({...x,code:m.code,mod:m.name})));
  ex.sort((a,b)=>a.d.localeCompare(b.d));
  $("#examTable").innerHTML=ex.map(x=>`<tr>
    <td class="mono" style="color:var(--red)">${fmtD(x.d)}</td>
    <td><span class="chip c" style="margin-right:8px">${x.code}</span></td>
    <td style="font-weight:600">${x.n}</td><td class="mono">${x.dur}</td><td style="color:var(--muted)">${x.mode}</td>
    <td class="mono" style="color:var(--amber)">${x.p}%</td></tr>`).join("");
  const res=s=>s>=9?"MAT. HONOR":s>=7?"NOTABLE":s>=6?"APROBADO":"SUSPENSO";
  const resC=s=>s>=9?"g":s>=7?"c":s>=6?"a":"r";
