function makeChat(msgsSel,inpSel,btnSel,chipSel,greet){
  const msgs=$(msgsSel),inp=$(inpSel),btn=$(btnSel);
  function add(role,html){const d=document.createElement("div");d.className="msg "+role;
    d.innerHTML=`<span class="who">${role==="ai"?"ASTRA":"ALEX MARTÍN"}</span><span class="body">${html}</span>`;
    msgs.appendChild(d);msgs.scrollTop=msgs.scrollHeight;return d;}
  function type(text){const d=add("ai","");const body=d.querySelector(".body");
    body.innerHTML='<span class="typing"><i></i><i></i><i></i></span>';
    setTimeout(()=>{body.textContent="";let i=0;
      const iv=setInterval(()=>{body.textContent=text.slice(0,++i);msgs.scrollTop=msgs.scrollHeight;
        if(i>=text.length){clearInterval(iv);}},11);},650);}
  function send(){const v=inp.value.trim();if(!v)return;add("user",v.replace(/</g,"&lt;"));inp.value="";setTimeout(()=>type(astraReply(v)),350);}
  btn.addEventListener("click",send);
  inp.addEventListener("keydown",e=>{if(e.key==="Enter")send()});
  if(chipSel)$$(chipSel).forEach(c=>c.addEventListener("click",()=>{inp.value=c.dataset.say;send()}));
  setTimeout(()=>type(greet),500);
}
