function renderSearch(f=""){selIdx=0;const list=INDEX.filter(i=>i.t.toLowerCase().includes(f.toLowerCase())).slice(0,9);
  $("#searchRes").innerHTML=list.length?list.map((i,k)=>`<div class="sr-item ${k===0?"sel":""}" data-v="${i.v}"><b>${i.t}</b><span class="chip">${i.tag}</span></div>`).join("")
   :'<div class="sr-item"><b style="color:var(--faint)">Sin resultados para "'+f.replace(/</g,"&lt;")+'"</b></div>';
  $$("#searchRes .sr-item").forEach(it=>it.addEventListener("click",()=>{if(it.dataset.v){closeSearch();switchView(it.dataset.v)}}));}
function openSearch(){$("#searchOv").classList.add("open");$("#searchInp").value="";renderSearch();setTimeout(()=>$("#searchInp").focus(),50)}
