.wq{background:var(--amber)} .wl{background:var(--cyan)} .wm{background:var(--violet)} .wf{background:var(--red)}
.reveal{opacity:0;transform:translateY(16px);transition:opacity .6s ease,transform .6s cubic-bezier(.2,.8,.2,1)}
.reveal.in{opacity:1;transform:none}

/* ============ DASHBOARD ============ */
.hello-row{display:grid;grid-template-columns:1.9fr 1fr;gap:18px;margin-bottom:18px}
.hello{padding:26px 28px;position:relative;overflow:hidden}
.hello::after{content:"";position:absolute;right:-60px;top:-60px;width:260px;height:260px;border:1px solid var(--line);border-radius:50%;opacity:.5}
.hello::before{content:"";position:absolute;right:-20px;top:-20px;width:180px;height:180px;border:1px dashed var(--line2);border-radius:50%;opacity:.6}
.hello .lbl{color:var(--green)}
.hello h1{font-family:var(--disp);font-size:clamp(28px,3.4vw,42px);font-weight:700;line-height:1.1;margin:8px 0 10px;letter-spacing:-.01em}
.hello p{color:var(--muted);max-width:560px;font-size:14px}
.hello p b{color:var(--cyan);font-weight:600}
.hello-cta{display:flex;gap:10px;margin-top:20px;flex-wrap:wrap}
.threat-board .levels{display:flex;gap:5px;margin:12px 0 16px}
.threat-board .levels i{height:8px;flex:1;border-radius:3px;background:rgba(255,255,255,.07)}
.threat-board .levels i.on{background:var(--amber);box-shadow:0 0 10px rgba(245,185,66,.5)}
.intel{display:flex;flex-direction:column;gap:9px}
.intel-row{display:flex;gap:10px;font-family:var(--mono);font-size:11px;color:var(--ink2);align-items:baseline}
.intel-row .t{color:var(--faint);flex-shrink:0}
.intel-row b{font-weight:500}
.intel-row .sev{margin-left:auto;flex-shrink:0}
.stats-strip{display:grid;grid-template-columns:repeat(5,1fr);gap:18px;margin-bottom:18px}
.stat{padding:18px 20px;position:relative}
.stat::before{content:"";position:absolute;top:0;left:20px;width:34px;height:2px;background:var(--green)}
.stat:nth-child(2)::before{background:var(--cyan)}
.stat:nth-child(3)::before{background:var(--amber)}
.stat:nth-child(4)::before{background:var(--violet)}
.stat:nth-child(5)::before{background:var(--red)}
.stat .num{font-family:var(--disp);font-size:38px;font-weight:700;line-height:1.05;letter-spacing:-.02em}
.stat .num small{font-size:16px;color:var(--faint);font-weight:500}
.stat .lbl{margin-top:6px}
.stat .delta{font-family:var(--mono);font-size:10px;color:var(--green);margin-top:6px}
.stat .delta.dn{color:var(--red)}
.dash-cols{display:grid;grid-template-columns:1.75fr 1fr;gap:18px;align-items:start}
.countdown{display:flex;gap:12px;margin:14px 0}
.cd-box{flex:1;text-align:center;border:1px solid var(--line2);border-radius:9px;padding:12px 6px;background:var(--panel3)}
.cd-box b{font-family:var(--disp);font-size:30px;font-weight:700;display:block;color:var(--amber);font-variant-numeric:tabular-nums}
.cd-box span{font-family:var(--mono);font-size:9px;letter-spacing:.18em;color:var(--faint);text-transform:uppercase}
.agenda{display:flex;flex-direction:column}
.agenda-row{display:flex;gap:14px;padding:11px 0;border-bottom:1px dashed var(--line);align-items:baseline}
.agenda-row:last-child{border-bottom:none}
.agenda-row .tm{font-family:var(--mono);font-size:11.5px;color:var(--cyan);flex-shrink:0;width:52px}
.agenda-row b{font-size:13px;font-weight:600;display:block}
.agenda-row span{font-size:11.5px;color:var(--muted)}
.feed-row{display:flex;align-items:center;gap:12px;padding:11px 0;border-bottom:1px dashed var(--line)}
.feed-row:last-child{border:none}
.feed-row .score{font-family:var(--disp);font-weight:700;font-size:16px;min-width:52px;text-align:center;padding:5px 8px;border-radius:7px}
.score.hi{background:var(--green-soft);color:var(--green)}
.score.mid{background:var(--amber-soft);color:var(--amber)}
.score.badge-s{background:var(--violet-soft);color:var(--violet);font-size:15px}
.feed-row b{font-size:13px;display:block}
.feed-row span{font-family:var(--mono);font-size:10px;color:var(--faint)}
.feed-row .when{margin-left:auto;font-family:var(--mono);font-size:10px;color:var(--faint);flex-shrink:0}
/* Astra widget */
.chat{display:flex;flex-direction:column}
.chat-msgs{padding:16px;display:flex;flex-direction:column;gap:12px;max-height:340px;overflow-y:auto}
.msg{max-width:88%;padding:10px 14px;border-radius:10px;font-size:13px;line-height:1.55;animation:msgIn .35s ease}
@keyframes msgIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.msg.ai{background:var(--panel3);border:1px solid var(--line);border-left:2px solid var(--violet);align-self:flex-start}
.msg.user{background:var(--green-soft);border:1px solid rgba(63,224,129,.35);align-self:flex-end}
.msg .who{font-family:var(--mono);font-size:9px;letter-spacing:.18em;text-transform:uppercase;display:block;margin-bottom:5px;color:var(--violet)}
.msg.user .who{color:var(--green)}
.typing{display:inline-flex;gap:4px;padding:4px 0}
.typing i{width:6px;height:6px;border-radius:50%;background:var(--violet);animation:tp 1.2s infinite}
.typing i:nth-child(2){animation-delay:.2s}.typing i:nth-child(3){animation-delay:.4s}
@keyframes tp{0%,100%{opacity:.25;transform:translateY(0)}50%{opacity:1;transform:translateY(-4px)}}
.chat-in{display:flex;gap:8px;padding:12px 16px;border-top:1px solid var(--line)}
.chat-in input{flex:1;background:var(--panel3);border:1px solid var(--line2);border-radius:8px;padding:10px 14px;color:var(--ink);font-family:var(--body);font-size:13px;transition:border-color .2s}
.chat-in input:focus{outline:none;border-color:var(--violet)}
.chat-in button{width:40px;border-radius:8px;border:1px solid rgba(183,156,255,.45);background:var(--violet-soft);color:var(--violet);display:grid;place-items:center;transition:all .2s}
.chat-in button:hover{background:var(--violet);color:#160f2b}
.chat-chips{display:flex;gap:8px;flex-wrap:wrap;padding:0 16px 14px}
.chat-chips .chip{cursor:pointer;transition:all .18s}
.chat-chips .chip:hover{border-color:var(--violet);color:var(--violet);transform:translateY(-1px)}
.mini-skill{display:flex;flex-direction:column;gap:12px}
.mini-skill .row .top{display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px}
.mini-skill .row .top b{font-weight:600}
.mini-skill .row .top span{font-family:var(--mono);font-size:11px;color:var(--muted)}
.q-links{display:flex;flex-direction:column;gap:8px}
.q-links .btn{justify-content:center}

/* ============ CURRICULUM ============ */
.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:20px;flex-wrap:wrap}
.page-head h1{font-family:var(--disp);font-size:clamp(26px,3vw,38px);font-weight:700;letter-spacing:-.01em;line-height:1.1}
.page-head p{color:var(--muted);max-width:640px;margin-top:8px;font-size:13.5px}
.page-head .lbl{color:var(--green);display:block;margin-bottom:8px}
.org-chips{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0 20px}
.policy-card{margin-bottom:22px}
.policy-grid{display:grid;grid-template-columns:1.4fr 1fr;gap:26px;align-items:center}
.policy-legend{display:flex;flex-direction:column;gap:8px}
.policy-legend .li{display:flex;align-items:center;gap:10px;font-size:12.5px}
.policy-legend .sw{width:11px;height:11px;border-radius:3px;flex-shrink:0}
.policy-legend b{font-family:var(--mono);font-size:12px;margin-left:auto;color:var(--ink2)}
.ytabs{display:flex;gap:8px;margin-bottom:20px;flex-wrap:wrap}
.ytab{padding:9px 18px;border-radius:8px;border:1px solid var(--line);background:var(--panel);color:var(--muted);font-family:var(--disp);font-weight:600;font-size:13px;transition:all .2s}
.ytab:hover{color:var(--ink);border-color:var(--line2)}
.ytab.active{background:var(--green-soft);border-color:rgba(63,224,129,.45);color:var(--green);box-shadow:0 0 18px rgba(63,224,129,.12)}
.sem{margin-bottom:26px}
.sem-head{display:flex;align-items:baseline;gap:14px;padding:0 4px 10px;border-bottom:1px solid var(--line2);margin-bottom:12px}
.sem-head h2{font-family:var(--disp);font-size:19px;font-weight:700}
.sem-head .term{font-family:var(--mono);font-size:11px;color:var(--cyan);letter-spacing:.1em}
.sem-head .meta{margin-left:auto;font-family:var(--mono);font-size:11px;color:var(--muted)}
.mod{border:1px solid var(--line);border-radius:10px;background:var(--panel);margin-bottom:10px;overflow:hidden;transition:border-color .2s}
.mod:hover{border-color:var(--line2)}
.mod summary{list-style:none;cursor:pointer;display:grid;grid-template-columns:86px 1fr 64px 180px 130px 30px;gap:14px;align-items:center;padding:14px 18px}
.mod summary::-webkit-details-marker{display:none}
.mod .code{font-family:var(--mono);font-size:11px;color:var(--cyan);border:1px solid rgba(95,212,240,.3);padding:4px 0;text-align:center;border-radius:5px;background:var(--cyan-soft)}
.mod .nm b{font-size:13.5px;font-weight:600;display:block}
.mod .nm span{font-size:11.5px;color:var(--muted)}
.mod .cr{font-family:var(--mono);font-size:12px;color:var(--ink2);text-align:center}
.mod .cr small{display:block;font-size:9px;color:var(--faint);letter-spacing:.15em}
.mod .st{text-align:right;font-family:var(--mono);font-size:12px}
.mod .st .gr{font-family:var(--disp);font-weight:700;font-size:17px}
.mod .chev{color:var(--faint);transition:transform .25s;text-align:center}
.mod[open] .chev{transform:rotate(180deg);color:var(--green)}
.mod-body{padding:6px 18px 18px;border-top:1px dashed var(--line);display:grid;grid-template-columns:1fr 1fr;gap:20px}
.mod-body h5{font-family:var(--mono);font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--faint);margin-bottom:10px}
.topics{display:flex;flex-wrap:wrap;gap:7px}
.ev-row{display:flex;gap:12px;padding:7px 0;border-bottom:1px dashed var(--line);font-size:12.5px;align-items:baseline}
.ev-row:last-child{border:none}
.ev-row .d{font-family:var(--mono);font-size:11px;color:var(--amber);width:84px;flex-shrink:0}
.ev-row .d.past{color:var(--faint)}
.ev-row b{font-weight:500}
.ev-row .pts{margin-left:auto;font-family:var(--mono);font-size:11.5px}
.pts.ok{color:var(--green)} .pts.md{color:var(--amber)} .pts.pend{color:var(--faint)}
.archived{font-family:var(--mono);font-size:11.5px;color:var(--muted);line-height:2}
.archived b{color:var(--green);font-weight:600}

/* ============ ASSESSMENTS ============ */
.ass-grid{display:grid;grid-template-columns:1.6fr 1fr;gap:18px;align-items:start}
.big-stack{height:26px;border-radius:7px;margin:18px 0 8px;position:relative}
.big-stack span{display:flex;align-items:center;justify-content:center;font-family:var(--mono);font-size:10px;color:#04140b;font-weight:600;overflow:hidden}
.scale{display:flex;justify-content:space-between;font-family:var(--mono);font-size:10px;color:var(--faint)}
.quiz-item{display:flex;align-items:center;gap:14px;padding:13px 18px;border-bottom:1px solid var(--line);transition:background .18s}
.quiz-item:hover{background:rgba(255,255,255,.02)}
.quiz-item:last-child{border:none}
.q-date{flex-shrink:0;text-align:center;border:1px solid var(--line2);border-radius:8px;padding:6px 10px;background:var(--panel3);min-width:58px}
.q-date b{font-family:var(--disp);font-size:19px;font-weight:700;display:block;line-height:1}
.q-date span{font-family:var(--mono);font-size:9px;letter-spacing:.18em;color:var(--faint)}
.quiz-item .qi b{display:block;font-size:13px;font-weight:600}
.quiz-item .qi span{font-family:var(--mono);font-size:10.5px;color:var(--muted)}
.quiz-item .w{margin-left:auto;text-align:right}
.quiz-item .w b{font-family:var(--disp);font-size:15px}
.quiz-item .w span{display:block;font-family:var(--mono);font-size:9.5px;color:var(--faint)}
.dleft{font-family:var(--mono);font-size:10px;padding:3px 9px;border-radius:20px;flex-shrink:0}
.dleft.urgent{background:var(--red-soft);color:var(--red);border:1px solid rgba(255,107,107,.35)}
.dleft.soon{background:var(--amber-soft);color:var(--amber);border:1px solid rgba(245,185,66,.35)}
.dleft.later{background:var(--cyan-soft);color:var(--cyan);border:1px solid rgba(95,212,240,.35)}
.honor{border-left:3px solid var(--green)}
.honor .card-b{font-size:12.5px;color:var(--muted);line-height:1.7}
.honor .card-b b{color:var(--ink2)}
.honor ul{margin:10px 0 0 16px}
.honor li{margin-bottom:5px}

/* ============ LABS ============ */
.lab-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-bottom:20px}
.lab-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin-bottom:20px}
.lab-card{padding:18px 20px;position:relative}
.lab-card .top{display:flex;align-items:flex-start;gap:12px;margin-bottom:10px}
.lab-card .code{font-family:var(--mono);font-size:11px;color:var(--green)}
.lab-card h4{font-family:var(--disp);font-size:16px;font-weight:600;margin:2px 0 6px}
.lab-card p{font-size:12.5px;color:var(--muted);min-height:38px}
.status-dot{width:9px;height:9px;border-radius:50%;margin-left:auto;margin-top:4px;flex-shrink:0}
.status-dot.on{background:var(--green);box-shadow:0 0 10px var(--green);animation:pulse 2s infinite}
.status-dot.mant{background:var(--amber);box-shadow:0 0 10px var(--amber);animation:pulse 1.2s infinite}
.status-dot.gate{background:var(--violet);box-shadow:0 0 10px var(--violet)}
.lab-meta{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}
.lab-occ{margin:12px 0 6px}
.lab-occ .lbl{display:flex;justify-content:space-between;margin-bottom:6px;letter-spacing:.12em}
.lab-occ .lbl b{color:var(--ink2);font-size:10.5px}
.diff{display:flex;gap:3px}
.diff i{width:14px;height:5px;border-radius:2px;background:rgba(255,255,255,.09)}
.diff i.on{background:var(--red)}
.lab-foot{display:flex;align-items:center;gap:10px;margin-top:14px}
.lab-foot .btn{margin-left:auto}
.lb-rank{font-family:var(--disp);font-weight:700;font-size:15px;width:34px;color:var(--faint)}
.lb-rank.r1{color:var(--amber)} .lb-rank.r2{color:var(--cyan)} .lb-rank.r3{color:var(--green)}
td .team{font-weight:600}
td .pts-mono{font-family:var(--mono);color:var(--green)}
tr.me{background:var(--green-soft)}

/* ============ COMPETENCIES ============ */
.comp-grid{display:grid;grid-template-columns:1fr 1.4fr;gap:18px;align-items:start;margin-bottom:18px}
.radar-wrap{display:flex;justify-content:center;padding:10px 0}
.radar-note{font-family:var(--mono);font-size:10.5px;color:var(--faint);text-align:center;padding:0 18px 16px;line-height:1.7}
.dom-row{padding:13px 0;border-bottom:1px dashed var(--line)}
.dom-row:last-child{border:none}
.dom-row .top{display:flex;align-items:baseline;gap:10px;margin-bottom:7px}
.dom-row .top b{font-size:13.5px;font-weight:600}
.dom-row .top .ev{font-family:var(--mono);font-size:10px;color:var(--faint)}
.dom-row .top .pct{margin-left:auto;font-family:var(--disp);font-weight:700;font-size:16px}
.dom-row .sub{display:flex;gap:8px;margin-top:7px;align-items:center}
.evid{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px dashed var(--line)}
.evid:last-child{border:none}
.evid .ico{width:36px;height:36px;border-radius:8px;display:grid;place-items:center;font-size:15px;flex-shrink:0;border:1px solid var(--line2)}
.evid b{font-size:12.5px;display:block}
.evid span{font-family:var(--mono);font-size:10px;color:var(--faint)}
.evid .chip{margin-left:auto}

/* ============ COMMUNITY ============ */
.com-grid{display:grid;grid-template-columns:1.7fr 1fr;gap:18px;align-items:start}
.thread{display:flex;gap:14px;padding:15px 18px;border-bottom:1px solid var(--line);transition:background .18s;cursor:pointer}
.thread:hover{background:rgba(255,255,255,.02)}
.thread:last-child{border:none}
.thread .rep{width:44px;flex-shrink:0;text-align:center}
.thread .rep b{font-family:var(--disp);font-size:17px;font-weight:700;display:block;color:var(--cyan)}
.thread .rep span{font-family:var(--mono);font-size:8.5px;letter-spacing:.12em;color:var(--faint)}
.thread .tt b{font-size:13.5px;font-weight:600;display:block;margin-bottom:5px}
.thread .tt .tags{display:flex;gap:6px;flex-wrap:wrap}
.thread .last{margin-left:auto;text-align:right;font-family:var(--mono);font-size:10px;color:var(--faint);flex-shrink:0;align-self:center}
.grp{display:flex;align-items:center;gap:12px;padding:11px 0;border-bottom:1px dashed var(--line)}
.grp:last-child{border:none}
.grp .g-ico{width:34px;height:34px;border-radius:8px;background:var(--panel3);border:1px solid var(--line2);display:grid;place-items:center;font-size:14px}
.grp b{font-size:12.5px;display:block}
.grp span{font-family:var(--mono);font-size:10px;color:var(--faint)}
.grp .chip{margin-left:auto}
.ev-item{display:flex;gap:12px;padding:11px 0;border-bottom:1px dashed var(--line)}
.ev-item:last-child{border:none}
.ev-item .ed{flex-shrink:0;text-align:center;border-right:1px solid var(--line);padding-right:12px}
.ev-item .ed b{font-family:var(--disp);font-size:18px;font-weight:700;color:var(--amber);display:block;line-height:1}
.ev-item .ed span{font-family:var(--mono);font-size:8.5px;letter-spacing:.15em;color:var(--faint)}
.ev-item b{font-size:12.5px;display:block;margin-bottom:3px}
.ev-item p{font-family:var(--mono);font-size:10.5px;color:var(--muted)}

/* ============ ASTRA FULL ============ */
.astra-grid{display:grid;grid-template-columns:1.7fr 1fr;gap:18px;align-items:stretch}
.astra-chat-card{display:flex;flex-direction:column;min-height:560px}
.astra-chat-card .chat-msgs{flex:1;max-height:none}
.pol-list{display:flex;flex-direction:column;gap:10px}
.pol-list .li{display:flex;gap:10px;font-size:12.5px;color:var(--muted);align-items:baseline}
.pol-list .li::before{content:"✓";color:var(--green);font-weight:700;flex-shrink:0}
.pol-list .li.no::before{content:"✕";color:var(--red)}
.astra-id{display:flex;align-items:center;gap:14px;padding:16px 18px;border:1px solid var(--line);border-radius:10px;background:linear-gradient(135deg,rgba(183,156,255,.08),transparent);margin-bottom:16px}
.astra-id .orb{width:46px;height:46px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#e3d7ff,var(--violet) 55%,#5a3fb8);box-shadow:0 0 26px rgba(183,156,255,.45);animation:breathe 3.5s ease-in-out infinite;flex-shrink:0}
@keyframes breathe{0%,100%{transform:scale(1)}50%{transform:scale(1.08)}}
.astra-id b{font-family:var(--disp);font-size:16px}
.astra-id span{display:block;font-family:var(--mono);font-size:10px;color:var(--muted);margin-top:3px}

/* ============ SEARCH OVERAY / TOAST / FOOTER ============ */
.search-ov{position:fixed;inset:0;z-index:90;background:rgba(5,8,12,.75);backdrop-filter:blur(6px);display:none;align-items:flex-start;justify-content:center;padding-top:12vh}
.search-ov.open{display:flex;animation:viewIn .25s ease}
.search-box{width:min(620px,92vw);background:var(--panel2);border:1px solid var(--line2);border-radius:12px;overflow:hidden;box-shadow:0 30px 80px rgba(0,0,0,.6)}
.search-box input{width:100%;background:transparent;border:none;padding:18px 20px;color:var(--ink);font-size:15px;font-family:var(--body)}
.search-box input:focus{outline:none}
#searchRes{max-height:320px;overflow-y:auto;border-top:1px solid var(--line)}
.sr-item{display:flex;align-items:center;gap:12px;padding:12px 20px;cursor:pointer;transition:background .15s;border-bottom:1px solid rgba(28,42,56,.5)}
.sr-item:hover,.sr-item.sel{background:var(--green-soft)}
.sr-item b{font-size:13px;font-weight:500}
.sr-item .chip{margin-left:auto}
.search-hint{padding:10px 20px;font-size:10px;color:var(--faint);border-top:1px solid var(--line)}
#toasts{position:fixed;bottom:24px;right:24px;z-index:100;display:flex;flex-direction:column;gap:10px}
.toast{display:flex;align-items:center;gap:12px;background:var(--panel2);border:1px solid var(--line2);border-left:3px solid var(--green);
  padding:13px 18px;border-radius:9px;font-size:13px;box-shadow:0 16px 40px rgba(0,0,0,.5);animation:toastIn .35s cubic-bezier(.2,.8,.2,1);max-width:360px}
.toast.warn{border-left-color:var(--amber)}
.toast.info{border-left-color:var(--cyan)}
@keyframes toastIn{from{opacity:0;transform:translateX(30px)}to{opacity:1;transform:none}}
.toast.out{opacity:0;transform:translateX(30px);transition:all .3s}
.site-foot{border-top:1px solid var(--line);margin-top:40px;padding-top:18px;display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  font-family:var(--mono);font-size:10px;color:var(--faint);letter-spacing:.08em}
.site-foot b{color:var(--muted);font-weight:500}

/* ============ RESPONSIVE ============ */
@media(max-width:1180px){
  .hello-row,.dash-cols,.ass-grid,.comp-grid,.com-grid,.astra-grid,.policy-grid{grid-template-columns:1fr}
  .stats-strip,.lab-strip{grid-template-columns:repeat(2,1fr)}
  .lab-grid{grid-template-columns:1fr}
}
@media(max-width:920px){
  .sidebar{width:70px;padding:16px 8px}
  .sidebar .lbl,.sidebar .nav-lbl,.brand-name,.brand-sub,.nav-btn .txt,.astra-mini div,.user-card div,.nav-badge,.astra-dot{display:none}
  .nav-btn{justify-content:center}
  .brand{justify-content:center;padding-bottom:14px}
  .astra-mini,.user-card{justify-content:center}
  .mod summary{grid-template-columns:70px 1fr 100px;grid-template-rows:auto auto}
  .mod .cr,.mod .st{grid-column:span 1}
  .mod-body{grid-template-columns:1fr}
  .date-chip,.search-btn kbd{display:none}
  .content{padding:18px 14px 50px}
}
</style>
