/* ═════════════════ UTILIDADES ═════════════════ */
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const fmtD=iso=>new Date(iso+"T12:00:00").toLocaleDateString("es-ES",{day:"2-digit",month:"short"}).toUpperCase().replace(".","");
const daysLeft=iso=>Math.ceil((new Date(iso+"T23:59:00")-new Date())/864e5);
function toast(msg,type=""){const t=document.createElement("div");t.className="toast "+type;t.innerHTML="<span style='font-size:15px'>"+(type==="warn"?"⚠":type==="info"?"◈":"✓")+"</span><span>"+msg+"</span>";$("#toasts").appendChild(t);setTimeout(()=>{t.classList.add("out");setTimeout(()=>t.remove(),320)},4200)}

/* ═════════════════ NAV ═════════════════ */
function switchView(v){
  $$(".view").forEach(x=>x.classList.remove("active"));
  $$(".nav-btn").forEach(b=>b.classList.toggle("active",b.dataset.view===v));
  const el=$("#view-"+v); el.classList.add("active");
  window.scrollTo({top:0,behavior:"smooth"});
  el.querySelectorAll(".reveal").forEach((r,i)=>{r.classList.remove("in");setTimeout(()=>r.classList.add("in"),60+i*50)});
  // re-animar barras del view
  setTimeout(()=>{el.querySelectorAll(".bar-fill").forEach(b=>{b.style.width="0";requestAnimationFrame(()=>requestAnimationFrame(()=>b.style.width=b.dataset.w))});
    el.querySelectorAll(".stack span").forEach(s=>{if(s.dataset.w){s.style.width="0";requestAnimationFrame(()=>requestAnimationFrame(()=>s.style.width=s.dataset.w))}})},120);
  if(v==="dashboard") runCounts();
}
$$(".nav-btn").forEach(b=>b.addEventListener("click",()=>switchView(b.dataset.view)));
document.addEventListener("click",e=>{
  const j=e.target.closest("[data-view-jump]"); if(j) switchView(j.dataset.viewJump);
  const t=e.target.closest("[data-toast]"); if(t) toast(t.dataset.toast);
});

/* ═════════════════ RELOJ / FECHA / SALUDO ═════════════════ */
function tickClock(){const d=new Date();$("#clock").textContent=d.toLocaleTimeString("es-ES");
  const chip=$("#dateChip"); const dd=d.toLocaleDateString("es-ES",{day:"2-digit",month:"short"}).toUpperCase().replace(".","");
  chip.innerHTML=dd+" "+d.getFullYear()+" · <b>WEEK 02</b> · FALL TERM";}
setInterval(tickClock,1000); tickClock();
(()=>{const h=new Date().getHours();const g=$("#greeting");
  g.textContent=(h<12?"Buenos días":h<20?"Buenas tardes":"Buenas noches")+", Alex."})();

/* ═════════════════ COUNTDOWN ═════════════════ */
const CD_TARGET=new Date("2026-09-10T23:59:00");
function tickCd(){const real=new Date();let diff=CD_TARGET-real;
  if(diff<0){const live=new Date(real.getTime()+ (1000*60*60*49.4)); diff=live-real;} // demo: siempre visible
  const d=Math.floor(diff/864e5),h=Math.floor(diff/36e5)%24,m=Math.floor(diff/6e4)%60,s=Math.floor(diff/1e3)%60;
  $("#cdD").textContent=d;$("#cdH").textContent=String(h).padStart(2,"0");$("#cdM").textContent=String(m).padStart(2,"0");$("#cdS").textContent=String(s).padStart(2,"0");}
setInterval(tickCd,1000); tickCd();

/* ═════════════════ CONTADORES ═════════════════ */
let counted=false;
function runCounts(){if(counted)return;counted=true;
  $$(".count").forEach(el=>{const target=parseFloat(el.dataset.v),dec=+el.dataset.d,t0=performance.now();
    const step=t=>{const p=Math.min((t-t0)/1400,1),e=1-Math.pow(1-p,3);el.textContent=(target*e).toFixed(dec);if(p<1)requestAnimationFrame(step)};
    requestAnimationFrame(step);});}

