/* ═════════════════ ASTRA CHAT ═════════════════ */
function astraReply(q){
  q=q.toLowerCase();
  if(/cripto|crypto|cry/.test(q))return "Tu dominio de criptografía está en 51% (el umbral de egreso es 60%). Mi recomendación inmediata: lab CRYPTO-007 (handshakes & key exchange) en CRYPTO-FORGE, que está al 12% de ocupación ahora mismo. Luego repasamos tus errores del Quiz 3 de CRY220: caíste en RSA con exponente pequeño y en padding OAEP. ¿Te genero un simulacro de 10 preguntas para el viernes?";
  if(/examen|quiz|parcial|midterm|evalua|calendario/.test(q))return "Esto es lo que tienes en cola: WRL360 Quiz 2 el 10/09 · OFF350 Quiz 3 el 12/09 · IOT370 Quiz 2 el 15/09 · AI380 Quiz 2 el 17/09 · LAB302 Quiz 2 el 18/09. Después: midterm OFF350 el 21/09 (presencial, SEB, 90 min). Consejo: dedica el fin de semana a ret2libc, es tu quiz más pesado. ¿Quieres el detalle de alguno?";
  if(/lab|rango|reserv/.test(q))return "Rangos con espacio ahora mismo: CRYPTO-FORGE 12% · MAL-SANDBOX 23% · OT-PLANT 38% · NET-RANGE 42%. RED-ARENA va por 81%, si la necesitas hoy reserva el slot de 16:00. Recuerda que MAL-SANDBOX entra en mantenimiento a las 02:00 UTC.";
  if(/competencia|skill|mapa|dominio/.test(q))return "Tu mapa hoy: Linux 91 · Networking 82 · Blue Team 77 · Forense 69 · Web 64 · Reverse 58 · Gobernanza 58 · Cripto 51. Los dos vértices bajo umbral son cripto y gobernanza. Tengo un plan de cierre de 4 semanas para cripto que subiría tu confianza unos 9 puntos. ¿Lo activamos?";
  if(/plan|semana|estudio|organiza/.test(q))return "Propuesta de semana: lunes WRL360 (Sigma rules, 90 min) · martes OFF350 ret2libc con lab guiado · miércoles tutoría de cripto conmigo 14:00 · jueves simulacro corto de IOT370 · viernes práctica CTF. Carga estimada: 11 h fuera de clase, dentro de tu media. Puedo bloquearlo en tu calendario si aceptas.";
  if(/tesis|capstone|año 4/.test(q))return "Para la tesis de Año 4 necesitas tutor asignado antes de la semana 3 de S7 y una propuesta con marco teórico (TH490, 2 ECTS). Con tu perfil, encajarías en la línea de Zero-Day Foundry o en seguridad de LLMs con la Dra. Salomon. El Capstone (CAP480) es una operación red/blue integral de 3 semanas evaluada 360°. ¿Quieres que compare líneas de investigación?";
  if(/fall|error|por qué|feedback/.test(q))return "Revisé tu Quiz 3 de CRY220: perdiste 1.4 pts en el ejercicio de RSA con e=3 (faltó el ataque de raíz cúbica) y 0.9 en la pregunta de modos CBC vs GCM. No es un problema de concepto, es práctica de ataques clásicos. Te propongo 5 ejercicios tipo antes del próximo parcial.";
  if(/hola|hey|buenas/.test(q))return "Hola, Alex. He revisado tu expediente esta mañana: 8.64 acumulado y racha de 14 días. Tu siguiente mejor acción sigue siendo criptografía — el lab CRYPTO-007 te espera y CRYPTO-FORGE está casi vacío. ¿Por dónde empezamos?";
  if(/gracias/.test(q))return "Para eso estoy. Cuando termines el CRYPTO-007, recalibramos tu confianza en el dominio y vemos el siguiente paso. Suerte con el Quiz 2 de WRL360. ⚡";
  return "Puedo ayudarte con planes de estudio, feedback de quizzes cerrados, reserva de labs y preparación de exámenes. Recuerda que por política académica no resuelvo evaluaciones activas ni modifico calificaciones — para eso está el Comité. ¿Qué necesitas exactamente?";
}
function makeChat(msgsSel,inpSel,btnSel,chipSel,greet){
  const msgs=$(msgsSel),inp=$(inpSel),btn=$(btnSel);
  function add(role,html){const d=document.createElement("div");d.className="msg "+role;
    d.innerHTML=`<span class="who">${role==="ai"?"ASTRA":"ALEX MARTÍN"}</span><span class="body">${html}</span>`;
    msgs.appendChild(d);msgs.scrollTop=msgs.scrollHeight;return d;}
  function type(text){const d=add("ai","");const body=d.querySelector(".body");
    body.innerHTML='<span class="typing"><i></i><i></i><i></i></span>';
    setTimeout(()=>{body.textContent="";let i=0;
      const iv=setInterval(()=>{body.textContent=text.slice(0,++i);msgs.scrollTop=msgs.scrollHeight;
        if(i>=text.length){clearInterval(iv);}},11);},650);}
  function send(){const v=inp.value.trim();if(!v)return;add("user",v.replace(/</g,"&lt;"));inp.value="";setTimeout(()=>type(astraReply(v)),350);}
  btn.addEventListener("click",send);
  inp.addEventListener("keydown",e=>{if(e.key==="Enter")send()});
  if(chipSel)$$(chipSel).forEach(c=>c.addEventListener("click",()=>{inp.value=c.dataset.say;send()}));
  setTimeout(()=>type(greet),500);
}
